import java.util.List;
import java.util.Map;

/**
 * One row from a workers collection. Expanded child accessors arrive as
 * nested collection envelopes ({ items, count, hasMore, limit, offset });
 * {@link #inline(String)} unwraps them to their items.
 */
public final class WorkerRecord {

    private final Map<String, Object> attrs;

    WorkerRecord(Map<String, Object> attrs) {
        this.attrs = attrs;
    }

    public String str(String name) {
        Object v = attrs.get(name);
        return v == null ? null : v.toString();
    }

    public Long num(String name) {
        Object v = attrs.get(name);
        if (v == null) return null;
        if (v instanceof Number n) return n.longValue();
        return Long.parseLong(v.toString());
    }

    @SuppressWarnings("unchecked")
    public List<WorkerRecord> inline(String childAccessor) {
        Object v = attrs.get(childAccessor);
        if (v == null) return List.of();
        Map<String, Object> envelope = (Map<String, Object>) v;
        List<Object> items = (List<Object>) envelope.get("items");
        if (items == null) return List.of();
        List<WorkerRecord> out = new ArrayList<>(items.size());
        for (Object item : items) {
            out.add(new WorkerRecord((Map<String, Object>) item));
        }
        return out;
    }
