    static WorkersPage parse(String body) {
        Map<String, Object> envelope = Json.parseObject(body);
        List<Object> rawItems = (List<Object>) envelope.getOrDefault("items", List.of());
        List<WorkerRecord> items = new ArrayList<>(rawItems.size());
        for (Object item : rawItems) {
            items.add(new WorkerRecord((Map<String, Object>) item));
