/**
 * Non-2xx answer from the HCM REST framework, carrying the structured error
 * document served under REST-Framework-Version 4+ (media type
 * application/vnd.oracle.adf.error+json): title, status (string form) and
 * every o:errorDetails entry in order. The message carries the document
 * title and the first application error code; credentials are never part
 * of the exception text.
 */
public class OracleRestException extends RuntimeException {

    private final int httpStatus;
    private final String title;
    private final String errorStatus;
    private final List<OracleErrorDetail> details;

    public OracleRestException(int httpStatus, String title, String errorStatus,
                               List<OracleErrorDetail> details) {
        super(buildMessage(httpStatus, title, details));
        this.httpStatus = httpStatus;
        this.title = title;
        this.errorStatus = errorStatus;
        this.details = List.copyOf(details);
    }

    private static String buildMessage(int httpStatus, String title,
                                       List<OracleErrorDetail> details) {
        StringBuilder sb = new StringBuilder("Oracle HCM REST request failed: HTTP ")
                .append(httpStatus);
        if (title != null && !title.isEmpty()) {
            sb.append(" — ").append(title);
        }
        if (!details.isEmpty() && details.get(0).errorCode() != null
                && !details.get(0).errorCode().isEmpty()) {
            sb.append(" [").append(details.get(0).errorCode()).append(']');
        }
        return sb.toString();
    }

    public int httpStatus() {
        return httpStatus;
    }

    public String title() {
        return title;
    }

    /** The error document's "status" field — the HTTP code as a string. */
    public String errorStatus() {
        return errorStatus;
    }

    public List<OracleErrorDetail> details() {
        return details;
    }
}
