/**
 * Headcount snapshot export: walks the whole workers collection effective
 * as of a given date and emits one 'PersonNumber|DisplayName' line per
 * worker, in PersonNumber order. The effective date is always passed
 * explicitly (the resource defaults to the current date otherwise), and
 * completeness comes from the hasMore-driven walk — totalResults is
 * surfaced for reporting only, as the estimate it is.
 */
public final class RosterExport {

    public record Result(List<String> lines, Long estimatedTotalResults, int pagesFetched) {}

    private RosterExport() {}

    public static Result effectiveRoster(HcmWorkersClient client, String effectiveDate,
                                         int pageSize) {
        WorkersQuery query = WorkersQuery.workers()
                .onlyData(true)
                .fields("PersonId", "PersonNumber", "DisplayName")
                .effectiveDate(effectiveDate)
                .orderBy("PersonNumber:asc")
                .totalResults(true)
                .limit(pageSize)
                .offset(0);
        List<WorkersPage> pages = client.fetchAll(query);
        List<WorkerRecord> workers = new ArrayList<>();
        for (WorkersPage page : pages) {
            workers.addAll(page.items());
        }
        workers.sort(Comparator.comparing(w -> w.str("PersonNumber")));
        List<String> lines = new ArrayList<>(workers.size());
        for (WorkerRecord w : workers) {
            lines.add(w.str("PersonNumber") + "|" + w.str("DisplayName"));
        }
        return new Result(List.copyOf(lines), pages.get(0).totalResults(), pages.size());
    }
